import React from 'react'

export default function sectionB() {
  const stories = [
    {
      name: "Sarah Johnson",
      program: "Computer Science, Class of 2023",
      story: "As a visually impaired student, the accommodation system provided me with digital textbooks and screen readers that transformed my learning experience. I graduated with honors thanks to their support.",
      image: "👩‍🎓",
      accommodations: ["Digital Textbooks", "Screen Readers", "Extended Exam Time"],
      rating: 5
    },
    {
      name: "Michael Chen",
      program: "Psychology, Graduate Student",
      story: "The mobility support services, including campus transportation and accessible classroom arrangements, allowed me to focus on my studies without worrying about physical barriers.",
      image: "👨‍🎓",
      accommodations: ["Campus Transportation", "Accessible Seating", "Note-taking Support"],
      rating: 5
    },
    {
      name: "Emma Rodriguez",
      program: "Business Administration",
      story: "Being hearing-impaired, I was provided with sign language interpreters and real-time captioning. The system made sure I never missed any important lectures or discussions.",
      image: "👩‍💼",
      accommodations: ["Sign Language Interpreter", "Real-time Captioning", "Visual Alerts"],
      rating: 4
    }
  ];

  return (
    <section className="py-16 px-4 sm:px-6 lg:px-8 bg-gradient-to-b from-blue-50 to-white">
      <div className="max-w-7xl mx-auto">
        <div className="text-center mb-12">
          <h2 className="text-3xl md:text-4xl font-bold text-gray-900 mb-4">
            Student Success Stories
          </h2>
          <p className="text-xl text-gray-600 max-w-3xl mx-auto">
            Hear from students who have thrived with our accessibility support
          </p>
          <div className="w-24 h-1 bg-blue-600 mx-auto mt-4"></div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
          {stories.map((student, index) => (
            <div key={index} className="group relative">
              <div className="absolute -inset-0.5 bg-gradient-to-r from-blue-600 to-purple-600 rounded-2xl blur opacity-25 group-hover:opacity-100 transition duration-300"></div>
              <div className="relative bg-white rounded-2xl p-8 shadow-lg">
                {/* Rating Stars */}
                <div className="flex mb-4">
                  {[...Array(5)].map((_, i) => (
                    <svg
                      key={i}
                      className={`w-5 h-5 ${i < student.rating ? 'text-yellow-400' : 'text-gray-300'}`}
                      fill="currentColor"
                      viewBox="0 0 20 20"
                    >
                      <path d="M9.049 2.927c.3-.921 1.603-.921 1.902 0l1.07 3.292a1 1 0 00.95.69h3.462c.969 0 1.371 1.24.588 1.81l-2.8 2.034a1 1 0 00-.364 1.118l1.07 3.292c.3.921-.755 1.688-1.54 1.118l-2.8-2.034a1 1 0 00-1.175 0l-2.8 2.034c-.784.57-1.838-.197-1.539-1.118l1.07-3.292a1 1 0 00-.364-1.118L2.98 8.72c-.783-.57-.38-1.81.588-1.81h3.461a1 1 0 00.951-.69l1.07-3.292z" />
                    </svg>
                  ))}
                </div>

                {/* Story */}
                <blockquote className="text-gray-600 italic mb-6">
                  {student.story}
                </blockquote>

                {/* Student Info */}
                <div className="flex items-center space-x-4">
                  <div className="w-16 h-16 bg-gradient-to-br from-blue-100 to-purple-100 rounded-full flex items-center justify-center text-3xl">
                    {student.image}
                  </div>
                  <div>
                    <div className="font-bold text-gray-900">{student.name}</div>
                    <div className="text-sm text-gray-500">{student.program}</div>
                  </div>
                </div>

                {/* Accommodations */}
                <div className="mt-6 pt-6 border-t border-gray-100">
                  <div className="text-sm font-semibold text-gray-700 mb-2">Accommodations Used:</div>
                  <div className="flex flex-wrap gap-2">
                    {student.accommodations.map((acc, idx) => (
                      <span
                        key={idx}
                        className="px-3 py-1 bg-blue-100 text-blue-800 text-xs font-medium rounded-full"
                      >
                        {acc}
                      </span>
                    ))}
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* Stats Bar */}
        <div className="mt-16 bg-gradient-to-r from-blue-600 to-purple-600 rounded-2xl shadow-xl p-8 text-white">
          <div className="grid grid-cols-2 md:grid-cols-4 gap-8">
            {[
              { number: "2,500+", label: "Students Supported" },
              { number: "98%", label: "Satisfaction Rate" },
              { number: "1.2k", label: "Monthly Requests" },
              { number: "24/7", label: "Support Available" }
            ].map((stat, index) => (
              <div key={index} className="text-center">
                <div className="text-3xl md:text-4xl font-bold mb-2">{stat.number}</div>
                <div className="text-blue-100">{stat.label}</div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
};

