export default function Hero() {
  return (
    <header className="relative bg-[#F3E3CD] overflow-hidden">
      <div className="max-w-7xl mx-auto px-6 pt-12 pb-16 lg:pb-24 grid grid-cols-1 lg:grid-cols-2 gap-12 items-center">
        
        {/* Left Content */}
        <div className="relative z-10">
          <svg className="hero-curve" viewBox="0 0 600 600" fill="none" xmlns="http://www.w3.org/2000/svg">
            <path d="M0 600 Q150 400 300 350 Q450 300 600 600 Z" fill="#9DCCB0" opacity="0.95"/>
          </svg>
          
          <div className="max-w-lg">
            <div className="inline-flex items-center gap-x-2 bg-white/80 backdrop-blur-md px-4 py-2 rounded-3xl text-[#41654F] text-sm font-medium mb-6">
              <span className="text-[#9DCCB0]">●</span>
              WE ARE REGISTERED NDIS PROVIDER
            </div>
            
            <h1 className="text-5xl lg:text-6xl font-bold leading-tight text-[#41654F]">
              DISABILITY<br/>HEALTH CARE<br/>SERVICES
            </h1>
            
            <p className="mt-6 text-lg text-[#705444] max-w-md">
              Professional, compassionate care tailored to your unique needs. 
              Registered NDIS provider delivering exceptional disability support.
            </p>
            
            <div className="mt-8 flex flex-wrap gap-4">
              <a href="#" 
                 className="bg-[#41654F] hover:bg-[#9DCCB0] hover:text-[#41654F] text-white px-8 py-4 rounded-2xl font-semibold flex items-center gap-x-3 transition-all">
                FREE CONSULTATION
                <i className="fa-solid fa-arrow-right"></i>
              </a>
              
              <a href="#" 
                 className="border-2 border-[#41654F] text-[#41654F] hover:bg-[#41654F] hover:text-white px-8 py-4 rounded-2xl font-semibold flex items-center gap-x-3 transition-all">
                <i className="fa-solid fa-play"></i>
                WATCH VIDEO
              </a>
            </div>
          </div>
        </div>

        {/* Right Image - fully responsive */}
        <div className="relative">
          <div className="bg-white rounded-3xl shadow-2xl overflow-hidden">
            <img 
              src="https://picsum.photos/id/1011/800/600" 
              alt="Elderly woman receiving care"
              className="w-full aspect-video lg:aspect-auto object-cover"
            />
          </div>
          <div className="absolute -top-6 -right-6 bg-[#9DCCB0] text-[#41654F] text-sm font-bold px-6 py-3 rounded-2xl shadow-xl rotate-12">
            24/7 SUPPORT
          </div>
        </div>
      </div>
    </header>
  );
}